<script setup>
import { computed } from 'vue';
const props=defineProps({detail:Object});
const p=computed(()=>props.detail?.submission?.payload||{}), patient=computed(()=>p.value.inline_patient||{});
const money=v=>Number(v||0).toLocaleString('ar-IQ')+' د.ع';
</script>
<template><div v-if="detail" class="submission-details"><h2>مراجعة الطلب #{{detail.submission.id}}</h2><div class="collection-stats"><div><small>اسم المريض</small><strong class="text-lg">{{patient.name}}</strong></div><div><small>العمر / تاريخ الميلاد</small><p>{{patient.age}} {{detail.references?.age_unit}} · {{patient.dob||'—'}}</p></div><div><small>الجنس</small><p>{{detail.references?.gender||'—'}}</p></div><div><small>جهة الإحالة</small><p>{{detail.source?.name||'مريض مباشر / سحب منزلي'}}</p></div><div><small>الهاتف</small><p dir="ltr">{{patient.phone_number||'—'}}</p></div><div><small>تاريخ التسجيل</small><p>{{p.registration_date}}</p></div></div><details class="my-4"><summary>معلومات المريض الإضافية</summary><dl class="collection-stats my-3"><div v-for="[field,label] in [['address','العنوان'],['email','البريد الإلكتروني'],['passport_no','رقم الجواز'],['national_id_no','رقم الهوية']]" :key="field"><dt>{{label}}</dt><dd>{{patient[field]||'—'}}</dd></div><div>الجنسية: {{detail.references?.nationality||'—'}}</div><div>اللقب: {{detail.references?.title||'—'}}</div></dl></details><img v-if="detail.image" :src="detail.image" alt="صورة المريض" class="max-w-40 rounded-xl my-3"><div class="collection-card" v-for="(item,i) in detail.items" :key="i"><div class="collection-tools"><strong>{{i+1}}. {{item.name}}</strong><span>{{money(item.price)}}</span></div><p v-for="(child,j) in [...(item.children||[]),...(item.cultures||[])]" :key="j">{{j+1}}. {{child.name}} · {{child.sample_name||'نوع العينة غير محدد'}}</p><p v-for="q in item.questions" :key="q.question.id">{{q.question.question}}: {{typeof q.answer==='boolean'?(q.answer?'نعم':'لا'):q.answer}}</p></div><div class="collection-stats"><div><small>مجموع التحاليل</small><strong>{{money(p.sub_total)}}</strong></div><div><small>الإجمالي</small><strong>{{money(p.total)}}</strong></div><div><small>المدفوع</small><strong>{{money(p.paid)}}</strong></div><div><small>المتبقي</small><strong>{{money(p.total-p.paid)}}</strong></div></div><p class="my-3">الخصم: {{p.discount||0}} {{p.discount_type_id_fk==2?'%':'د.ع'}} · مبلغ سجل العمل: {{p.work_register_amount==null?'غير محدد':money(p.work_register_amount)}}</p><p>الطبيب / الإحالة: {{detail.references?.referral||'—'}} · العقد: {{detail.references?.contract||'—'}}</p><p v-for="(payment,i) in p.payment_details" :key="i">دفعة {{i+1}}: {{money(payment.amount)}} · {{detail.references?.payments?.[payment.payment_method_id_fk]||'غير محدد'}}</p><p class="my-3 whitespace-pre-wrap">ملاحظات: {{p.notes||'—'}}</p><p v-if="detail.submission.review_note">قرار المراجعة: {{detail.submission.review_note}}</p></div></template>
